insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 26, 10529, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('national', 26, 10530, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('national', 36, 10503, false, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.'),
  ('national', 71, 10504, false, '꿀 냄새로 먹이를 끌어들인다. 입안에 넣은 것은 하루 만에 뼈까지 녹여버린다고 한다.', 'Lures prey with the sweet aroma of honey. Swallowed whole, the prey is dissolved in a day, bones and all.'),
  ('national', 121, 10505, false, '몸을 고속으로 회전시켜 바다를 헤엄치며 작은 플랑크톤을 흡수한다.', 'Starmie swims by spinning its body at high speed. As this Pokémon cruises through the ocean, it absorbs tiny plankton.'),
  ('national', 149, 10506, false, '바다의 화신이라고 불린다. 망나뇽 형태의 조각상을 뱃머리에 두는 배도 많다.', 'This Pokémon is known as the Sea Incarnate. Figureheads that resemble Dragonite decorate the bows of many ships.'),
  ('national', 154, 10507, false, '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', 'The fragrance of Meganium’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit.'),
  ('national', 160, 10508, false, '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', 'Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.'),
  ('national', 227, 10509, false, '빠진 깃털로 검을 만들 수 있어서 문장 도안으로 인기가 많다.', 'People fashion swords from Skarmory’s shed feathers, so this Pokémon is a popular element in heraldic designs.'),
  ('national', 358, 10531, false, '바람이 강해지면 나뭇가지나 처마 끝에 머리의 흡반으로 매달려 울기 시작한다. 긴 꼬리로 나무열매를 집어서 먹는다.', 'Can emit waves of air powerful enough to knock out prey taller than itself. I hypothesize that it amplifies the faint sound of wind within its body.'),
  ('national', 359, 10532, false, '위험을 감지하는 능력이 있어 사람들로부터 재앙을 불러오는 포켓몬이라는 오해를 샀다.', 'Because of this Pokémon’s ability to detect danger, people mistook Absol as a bringer of doom.'),
  ('national', 398, 10533, false, '찌르호크가 되면 무리에서 떨어져 혼자서 살아간다. 강인한 날개를 가지고 있다.', 'It has left the flock, having gained strength enough to survive on its own. The astounding force with which Staraptor flies through the air allows it to carry away large, burly targets.'),
  ('national', 445, 10534, false, '지상에서도 움직임이 빠르다. 설산에서는 체온이 떨어지기 전에 먹이를 잡아 거처로 돌아간다.', 'Soars across the heavens at blinding speed—a magnificent sight! It has a feral disposition. Utmost caution is required if one meets a Garchomp out in the wilds.'),
  ('national', 448, 10535, false, '사람이 생각하는 것도 알 수 있기 때문에 정직한 마음을 가진 트레이너만 따른다.', 'A most gallant-looking creature. It emits energy waves and controls them with precision, using them to sense even faraway beings. I have given the name ”aura” to this power.'),
  ('national', 478, 10510, false, '마이너스 50도의 냉기를 뿜어 먹이를 얼린 뒤 거처로 가져가서 가지런히 나열한다.', 'A Pokémon inhabited by the soul of a woman who died bearing a grudge in the snowy mountains. Legends of Froslass placing deathly curses on misbehaving men send shivers down my spine.'),
  ('national', 485, 10536, false, '마그마처럼 타오르는 혈액이 몸에서 흐르고 있다. 화산의 동굴에 서식한다.', 'Stories tell of this Pokémon being birthed from the boiling magma within Mount Coronet. Its molten-steel body holds many mysteries.'),
  ('national', 491, 10537, false, '사람들을 깊은 잠으로 끌어들여 꿈을 꾸게 하는 능력을 가지고 있다. 그믐달이 뜨는 밤에 활동한다.', 'On a moonless night, a strange incident occurred in which every one of a village''s inhabitants suffered nightmares. The villagers attested that Darkrai appeared before them in these nightmares.'),
  ('national', 500, 10511, false, '불꽃 턱수염을 기르고 있다. 파워와 스피드를 겸비한 격투 기술을 익히고 있다.', 'It has mastered fast and powerful fighting moves. It grows a beard of fire.'),
  ('national', 530, 10512, false, '별명은 드릴킹이다. 땅속을 파는 속도는 시속 150km에 달한다.', 'Known as the Drill King, this Pokémon can tunnel through the terrain at speeds of over 90 mph.'),
  ('national', 545, 10513, false, '영역을 두고 다태우지네와 격렬하게 다툰다. 패배한 쪽이 그대로 먹이가 된다.', 'Scolipede engage in fierce territorial battles with Centiskorch. At the end of one of these battles, the victor makes a meal of the loser.'),
  ('national', 560, 10514, false, '매우 거친 성격이지만 가족과 동료와 영역은 소중히 여긴다.', 'While mostly known for having the temperament of an aggressive ruffian, this Pokémon takes very good care of its family, friends, and territory.'),
  ('national', 604, 10515, false, '팔 힘으로 바다에서 기어 나와 물가에 있는 먹이를 덮친다. 한순간에 바다로 끌고 들어간다.', 'They crawl out of the ocean using their arms. They will attack prey on shore and immediately drag it into the ocean.'),
  ('national', 609, 10516, false, '샹델라를 등불 대용으로 사용했던 저택에서는 장례식이 끊이지 않았다고 한다.', 'In homes illuminated by Chandelure instead of lights, funerals were a constant occurrence— or so it’s said.'),
  ('national', 623, 10538, false, '체내에 에너지를 생성하는 영구 기관이 있다고 하지만 아직도 밝혀지지 않았다.', 'There’s a theory that inside Golurk is a perpetual motion machine that produces limitless energy, but this belief hasn’t been proven.'),
  ('national', 652, 10517, false, '얼굴 앞에 주먹을 맞대어 방어 포즈를 취하면 폭탄의 직격도 견뎌낸다.', 'When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.'),
  ('national', 655, 10518, false, '섭씨 3000도의 불꽃 소용돌이를 초능력으로 조종한다. 적을 소용돌이로 감싸 불태운다.', 'Using psychic power, it generates a fiery vortex of 5,400 degrees Fahrenheit, incinerating foes swept into this whirl of flame.'),
  ('national', 658, 10519, false, '닌자처럼 신출귀몰하다. 재빠른 움직임으로 상대를 농락하면서 물의 수리검으로 벤다.', 'It appears and vanishes with a ninja’s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.'),
  ('national', 668, 10520, false, '섭씨 6000도의 숨결을 내뱉지만 먹이에는 사용하지 않는다. 고기는 날것을 좋아하기 때문이다.', 'The temperature of its breath is over 10,000 degrees Fahrenheit, but Pyroar doesn’t use it on its prey. This Pokémon prefers to eat raw meat.'),
  ('national', 670, 10521, false, '자신의 파워를 꽃에 주고 진심을 담아 돌본다. 화단을 어지럽히는 자는 용서하지 않는다.', 'It gives its own power to flowers, pouring its heart into caring for them. Floette never forgives anyone who messes up a flower bed.'),
  ('national', 678, 10539, false, '수컷은 방어 본능이 강해서 자신과 파트너를 지킬 때 최대의 파워를 쓴다.', 'The defensive instinct of the males is strong. It’s when they’re protecting themselves or their partners that they unleash their full power.'),
  ('national', 678, 10554, false, '수컷은 방어 본능이 강해서 자신과 파트너를 지킬 때 최대의 파워를 쓴다.', 'The defensive instinct of the males is strong. It’s when they’re protecting themselves or their partners that they unleash their full power.'),
  ('national', 687, 10522, false, '역사를 바꿀 정도의 큰 사건은 칼라마네로의 최면 능력과 관련이 있다고 전해진다.', 'It’s said that Malamar’s hypnotic powers played a role in certain history-changing events.'),
  ('national', 689, 10523, false, '손바닥의 눈동자가 전후좌우를 감시한다. 위기에 처하면 손발이 멋대로 움직여 적을 쓰러뜨린다.', 'Having an eye on each palm allows it to keep watch in all directions. In a pinch, its limbs start to act on their own to ensure the enemy’s defeat.'),
  ('national', 691, 10524, false, '머리의 갓을 해면 위로 내밀고 태양 빛을 받아 드래곤 에너지를 만든다.', 'Dragalge generates dragon energy by sticking the plume on its head out above the ocean’s surface and bathing it in sunlight.'),
  ('national', 701, 10525, false, '끝을 내는 결정적인 기술을 쓰기 전에 반드시 포즈를 취한다. 그 틈에 반격당하기도 한다.', 'It always strikes a pose before going for its finishing move. Sometimes opponents take advantage of that time to counterattack.'),
  ('national', 718, 10526, false, '생태계를 위협하는 자와 싸울 때 더욱 강력한 모습으로 변화한다고 전해진다.', 'Some say it can change to an even more powerful form when battling those who threaten the ecosystem.'),
  ('national', 740, 10540, false, '생각하기보다는 일단 때리고 본다. 눈사태를 펀치 러시로 되받아쳤다는 기록도 있다.', 'Before it stops to think, it just starts pummeling. There are records of its turning back avalanches with a flurry of punches.'),
  ('national', 768, 10541, false, '해저의 굴이나 침몰선이 거처다. 케오퍼스와 싸워서 진 쪽이 먹이가 된다.', 'They live in sunken ships or in holes in the seabed. When Golisopod and Grapploct battle, the loser becomes the winner’s meal.'),
  ('national', 780, 10527, false, '사람을 잘 따르고 마음이 착하지만 한번 화가 나면 강풍을 일으켜 모든 것을 쓰러뜨려 버린다.', 'Drampa is a kind and friendly Pokémon—up until it’s angered. When that happens, it stirs up a gale and flattens everything around.'),
  ('national', 801, 10542, false, '약 500년 전 과학자에 의해 만들어졌다. 소울하트라고 불리는 파츠가 본체다.', 'Built roughly 500 years ago by a scientist, the part called the Soul-Heart is the actual life-form.'),
  ('national', 801, 10543, false, '약 500년 전 과학자에 의해 만들어졌다. 소울하트라고 불리는 파츠가 본체다.', 'Built roughly 500 years ago by a scientist, the part called the Soul-Heart is the actual life-form.'),
  ('national', 807, 10544, false, '손발의 볼록살에서 전기를 내보낸다. 제라오라가 달려나가면 번개가 치고 우렛소리가 울려 퍼진다.', 'Electricity sparks from the pads on its limbs. Wherever Zeraora runs, lightning flashes and thunder echoes.'),
  ('national', 870, 10528, false, '6마리가 1마리의 포켓몬이다. 대열을 바꿔가며 팀워크로 싸운다.', 'The six of them work together as one Pokémon. Teamwork is also their battle strategy, and they constantly change their formation as they fight.'),
  ('national', 952, 10545, false, null, 'The green head has turned vicious due to the spicy chemicals stimulating its brain. Once it goes on a rampage, there is no stopping it.'),
  ('national', 970, 10546, false, null, 'Glimmora’s petals are made of crystallized poison energy. It has recently become evident that these petals resemble Tera Jewels.'),
  ('national', 978, 10547, false, null, 'Tatsugiri is an extremely cunning Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.'),
  ('national', 978, 10548, false, null, 'Tatsugiri is an extremely cunning Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.'),
  ('national', 978, 10549, false, null, 'Tatsugiri is an extremely cunning Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.'),
  ('national', 998, 10550, false, null, 'It launches itself into battle by flipping upside down and spewing frigid air from its mouth. It finishes opponents off with its dorsal blade.'),
  ('kanto', 26, 10529, false, '몸에 전기가 모이면 공격적인 성격으로 변한다. 어두운 곳에서 빛나 보인다.', 'When electricity builds up inside its body, it becomes feisty. It also glows in the dark.'),
  ('kanto', 26, 10530, false, '몸에 전기가 모이면 공격적인 성격으로 변한다. 어두운 곳에서 빛나 보인다.', 'When electricity builds up inside its body, it becomes feisty. It also glows in the dark.'),
  ('kanto', 36, 10503, false, '자신들의 세계를 소중히 생각하고 있는 듯 좀처럼 사람 앞에 나타나지 않는 요정의 일종.', 'They appear to be very protective of their own world. It is a kind of fairy, rarely seen by people.'),
  ('kanto', 71, 10504, false, '꿀 냄새로 먹이를 끌어들인다. 입안에 넣은 것은 하루 만에 뼈까지 녹여버린다고 한다.', 'Lures prey with the sweet aroma of honey. Swallowed whole, the prey is dissolved in a day, bones and all.'),
  ('kanto', 121, 10505, false, '코어라고 불리는 중심 부분이 일곱 빛깔로 빛나는 것은 통신을 하고 있기 때문이라고 전해진다.', 'The center section is named the core. People think it is communicating when it glows in seven colors.'),
  ('kanto', 149, 10506, false, '넓은 바다 어딘가를 거처로 삼아 날아서 이동한다고 전해지지만 어디까지나 소문에 지나지 않는다.', 'It is said that this Pokémon lives somewhere in the sea and that it flies. However, these are only rumors.'),
  ('johto', 3, 10507, false, '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', 'The aroma that rises from its petals contains a substance that calms aggressive feelings.'),
  ('johto', 9, 10508, false, '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', 'When it bites with its massive and powerful jaws, it shakes its head and savagely tears its victim up.'),
  ('johto', 23, 10529, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'When its electricity builds, its muscles are stimulated, and it becomes more aggressive than usual.'),
  ('johto', 23, 10530, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'When its electricity builds, its muscles are stimulated, and it becomes more aggressive than usual.'),
  ('johto', 42, 10503, false, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'With its acute hearing, it can pick up sounds from far away. It usually hides in quiet places.'),
  ('johto', 66, 10504, false, '꿀 냄새로 먹이를 끌어들인다. 입안에 넣은 것은 하루 만에 뼈까지 녹여버린다고 한다.', 'Acid that has dissolved many prey becomes sweeter, making it even more effective at attracting prey.'),
  ('johto', 168, 10505, false, '몸을 고속으로 회전시켜 바다를 헤엄치며 작은 플랑크톤을 흡수한다.', 'The middle section of its body is called the core. It glows in a different color each time it is seen.'),
  ('johto', 198, 10509, false, '빠진 깃털로 검을 만들 수 있어서 문장 도안으로 인기가 많다.', 'Its sturdy wings look heavy, but they are actually hollow and light, allowing it to fly freely in the sky.'),
  ('johto', 243, 10506, false, '바다의 화신이라고 불린다. 망나뇽 형태의 조각상을 뱃머리에 두는 배도 많다.', 'It is said that this Pokémon constantly flies over the immense seas and rescues drowning people.'),
  ('hoenn', 115, 10509, false, '전신이 단단한 갑옷으로 둘러싸여 있다. 시속 300km의 스피드로 하늘을 날아 칼날 같은 날카로운 날개로 베어낸다.', 'Skarmory is entirely encased in hard, protective armor. This Pokémon flies at close to 190 mph. It slashes foes with its wings that possess swordlike cutting edges.'),
  ('hoenn', 144, 10505, false, '몸의 중심에 있는 핵이라 불리는 부분이 일곱 빛깔로 빛나기에 바다의 보석이라는 별명이 붙었다.', 'Starmie’s center section—the core—glows brightly in seven colors. Because of its luminous nature, this Pokémon has been given the nickname “the gem of the sea.”'),
  ('hoenn', 151, 10531, false, '목소리를 몸의 빈 곳에 메아리치게 한다. 화가 났을 때의 울음소리는 적을 날려버릴 위력을 지닌 초음파가 된다.', 'Chimecho makes its cries echo inside its hollow body. When this Pokémon becomes enraged, its cries result in ultrasonic waves that have the power to knock foes flying.'),
  ('hoenn', 152, 10532, false, '앱솔이 사람들 앞에 나타나면 반드시 지진이나 해일 등의 재해가 일어나서 재난포켓몬이라는 별명으로 불렸다.', 'Every time Absol appears before people, it is followed by a disaster such as an earthquake or a tidal wave. As a result, it came to be known as the disaster Pokémon.'),
  ('hoenn', 157, 10529, false, '전기 주머니에 전기가 넘칠 정도로 차면 꼬리를 땅에 닿게 하여 방전한다. 사는 곳 근처의 땅에는 탄 흔적이 있다.', 'If the electrical sacs become excessively charged, Raichu plants its tail in the ground and discharges. Scorched patches of ground will be found near this Pokémon’s nest.'),
  ('hoenn', 157, 10530, false, '전기 주머니에 전기가 넘칠 정도로 차면 꼬리를 땅에 닿게 하여 방전한다. 사는 곳 근처의 땅에는 탄 흔적이 있다.', 'If the electrical sacs become excessively charged, Raichu plants its tail in the ground and discharges. Scorched patches of ground will be found near this Pokémon’s nest.'),
  ('sinnoh', 12, 10533, false, '찌르호크가 되면 무리에서 떨어져 혼자서 살아간다. 강인한 날개를 가지고 있다.', 'It never stops attacking even if it is injured. It fusses over the shape of its comb.'),
  ('sinnoh', 83, 10531, false, '바람이 강해지면 나뭇가지나 처마 끝에 머리의 흡반으로 매달려 울기 시작한다. 긴 꼬리로 나무열매를 집어서 먹는다.', 'Its cries echo inside its hollow body to emerge as beautiful notes for startling and repelling foes.'),
  ('sinnoh', 101, 10503, false, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'It is very wary and rarely shows itself to people. Its ears can hear a pin drop over half a mile away.'),
  ('sinnoh', 105, 10529, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'Its tail discharges electricity into the ground, protecting it from getting shocked.'),
  ('sinnoh', 105, 10530, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'Its tail discharges electricity into the ground, protecting it from getting shocked.'),
  ('sinnoh', 111, 10534, false, '지상에서도 움직임이 빠르다. 설산에서는 체온이 떨어지기 전에 먹이를 잡아 거처로 돌아간다.', 'It is said that when one runs at high speed, its wings create blades of wind that can fell nearby trees.'),
  ('sinnoh', 116, 10535, false, '사람이 생각하는 것도 알 수 있기 때문에 정직한 마음을 가진 트레이너만 따른다.', 'A well-trained one can sense auras to identify and take in the feelings of creatures over half a mile away.'),
  ('sinnoh', 208, 10510, false, '마이너스 50도의 냉기를 뿜어 먹이를 얼린 뒤 거처로 가져가서 가지런히 나열한다.', 'It freezes prey by blowing its -58 degrees F breath. It is said to then secretly display its prey.'),
  ('sinnoh', 209, 10532, false, '위험을 감지하는 능력이 있어 사람들로부터 재앙을 불러오는 포켓몬이라는 오해를 샀다.', 'Rumored to sense disasters with its horn, it became a target. It fled deep into the mountains.'),
  ('sinnoh', 211, 10536, false, '마그마처럼 타오르는 혈액이 몸에서 흐르고 있다. 화산의 동굴에 서식한다.', 'Its body is made of rugged steel. However, it is partially melted in spots because of its own heat.'),
  ('sinnoh', 215, 10537, false, '사람들을 깊은 잠으로 끌어들여 꿈을 꾸게 하는 능력을 가지고 있다. 그믐달이 뜨는 밤에 활동한다.', 'To protect itself, it afflicts those around it with nightmares. However, it means no harm.'),
  ('unova', 6, 10511, false, '불꽃 턱수염을 기르고 있다. 파워와 스피드를 겸비한 격투 기술을 익히고 있다.', 'A flaring beard of fire is proof that it is fired up. It is adept at using many different moves.'),
  ('unova', 34, 10535, false, '사람이 생각하는 것도 알 수 있기 때문에 정직한 마음을 가진 트레이너만 따른다.', 'By reading the auras of all things, it can tell how others are feeling from over half a mile away.'),
  ('unova', 45, 10513, false, '영역을 두고 다태우지네와 격렬하게 다툰다. 패배한 쪽이 그대로 먹이가 된다.', 'It clasps its prey with the claws on its neck until it stops moving. Then it finishes it off with deadly poison.'),
  ('unova', 77, 10512, false, '별명은 드릴킹이다. 땅속을 파는 속도는 시속 150km에 달한다.', 'Forming a drill with its steel claws and head, it can bore through a steel plate, no matter how thick it is.'),
  ('unova', 90, 10503, false, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'Their ears are sensitive enough to hear a pin drop from over a mile away, so they’re usually found in quiet places.'),
  ('unova', 118, 10514, false, '매우 거친 성격이지만 가족과 동료와 영역은 소중히 여긴다.', 'It pulls up its shed skin to protect itself while it kicks. The bigger the crest, the more respected it is.'),
  ('unova', 179, 10515, false, '팔 힘으로 바다에서 기어 나와 물가에 있는 먹이를 덮친다. 한순간에 바다로 끌고 들어간다.', 'It latches on to prey with its sucker mouth, sinking in its fangs and shocking the prey with powerful electricity.'),
  ('unova', 192, 10516, false, '샹델라를 등불 대용으로 사용했던 저택에서는 장례식이 끊이지 않았다고 한다.', 'The spirits burned up in its ominous flame lose their way and wander this world forever.'),
  ('unova', 203, 10509, false, '빠진 깃털로 검을 만들 수 있어서 문장 도안으로 인기가 많다.', 'Its heavy-looking iron body is actually thin and light, so it can fly at speeds over 180 mph.'),
  ('unova', 216, 10532, false, '위험을 감지하는 능력이 있어 사람들로부터 재앙을 불러오는 포켓몬이라는 오해를 샀다.', 'It appears from deep in the mountains to warn people about upcoming disasters it has sensed with its horn.'),
  ('unova', 239, 10505, false, '몸을 고속으로 회전시켜 바다를 헤엄치며 작은 플랑크톤을 흡수한다.', 'Its core shines in many colors and sends radio signals into space to communicate with something.'),
  ('unova', 272, 10538, false, '체내에 에너지를 생성하는 영구 기관이 있다고 하지만 아직도 밝혀지지 않았다.', 'Golurk were created to protect people and Pokémon. They run on a mysterious energy.'),
  ('kalos', 3, 10517, false, '몸통박치기로 50톤 전차를 뒤집는 파워를 지녔다. 자신이 방패가 되어 동료를 지킨다.', 'Its Tackle is forceful enough to flip a 50-ton tank. It shields its allies from danger with its own body.'),
  ('kalos', 6, 10518, false, '지팡이 끝의 타오르는 불꽃을 바라보며 정신을 통일하면 미래에 일어날 일을 내다볼 수 있다.', 'It gazes into the flame at the tip of its branch to achieve a focused state, which allows it to see into the future.'),
  ('kalos', 9, 10519, false, '물을 압축시켜 수리검을 만들어 낸다. 고속으로 회전시키며 던지면 금속도 두 동강이 난다.', 'It creates throwing stars out of compressed water. When it spins them and throws them at high speed, these stars can split metal in two.'),
  ('kalos', 37, 10529, false, '전기가 모이면 근육이 자극되어 여느 때보다 공격적이 된다.', 'When its electricity builds, its muscles are stimulated, and it becomes more aggressive than usual.'),
  ('kalos', 37, 10530, false, '전기가 모이면 근육이 자극되어 여느 때보다 공격적이 된다.', 'When its electricity builds, its muscles are stimulated, and it becomes more aggressive than usual.'),
  ('kalos', 58, 10520, false, '무리 중에서 가장 커다란 불꽃 갈기를 지닌 수컷이 리더로서 동료들을 이끈다.', 'The male with the largest mane of fire is the leader of the pride.'),
  ('kalos', 63, 10535, false, '상대가 발하는 파동을 감지하여 생각이나 움직임을 간파할 수 있다.', 'By catching the aura emanating from others, it can read their thoughts and movements.'),
  ('kalos', 69, 10521, false, '꽃밭을 날아다니며 말라가는 꽃을 보살핀다. 꽃의 숨겨진 힘을 끌어내어 싸운다.', 'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the hidden power of flowers to battle.'),
  ('kalos', 101, 10514, false, '탈피한 가죽을 끌어 올려 데미지를 줄이면서 킥! 볏이 클수록 거만하다.', 'It pulls up its shed skin to protect itself while it kicks. The bigger the crest, the more respected it is.'),
  ('kalos', 115, 10539, false, '위험이 다가오면 귀를 들어 올리고 10톤 트럭을 눌러 부술 정도의 사이코 파워를 방출한다.', 'When in danger, it raises its ears and releases enough psychic power to grind a 10-ton truck into dust.'),
  ('kalos', 115, 10554, false, '위험이 다가오면 귀를 들어 올리고 10톤 트럭을 눌러 부술 정도의 사이코 파워를 방출한다.', 'When in danger, it raises its ears and releases enough psychic power to grind a 10-ton truck into dust.'),
  ('kalos', 122, 10513, false, '먹이를 목의 가시에 끼워 넣어 움직이지 못하게 한 후 맹독을 퍼뜨려 마무리한다.', 'It clasps its prey with the claws on its neck until it stops moving. Then it finishes it off with deadly poison.'),
  ('kalos', 159, 10532, false, '재해의 위험을 감지한다. 위험을 알리는 때에만 사람 앞에 나타난다고 한다.', 'It senses coming disasters and appears before people only to warn them of impending danger.'),
  ('kalos', 161, 10522, false, '포켓몬 중에서 가장 강력한 최면술을 쓴다. 상대를 자기 마음대로 조종해버린다.', 'It wields the most compelling hypnotic powers of any Pokémon, and it forces others to do whatever it wants.'),
  ('kalos', 172, 10523, false, '진화할 때 2마리의 거북손손이 7마리로 분열된 포켓몬이다. 7마리분의 파워로 싸운다.', 'When they evolve, two Binacle multiply into seven. They fight with the power of seven Binacle.'),
  ('kalos', 181, 10524, false, '유조선의 선체를 썩게 할 정도의 맹독을 영역 안에 들어 온 것에 무턱대고 끼얹는다', 'Their poison is strong enough to eat through the hull of a tanker, and they spit it indiscriminately at anything that enters their territory.'),
  ('kalos', 185, 10505, false, '코어라고 불리는 중심 부분은 일곱 빛깔로 빛난다. 이것을 보석으로 삼는 사람도 있다고 한다.', 'Its central core glows with the seven colors of the rainbow. Some people value the core as a gem.'),
  ('kalos', 239, 10525, false, '체격은 작지만 괴력몬이나 하리뭉 등의 커다란 포켓몬과 막상막하로 싸우는 테크니션이다.', 'Although its body is small, its proficient fighting skills enable it to keep up with big bruisers like Machamp and Hariyama.'),
  ('kalos', 242, 10538, false, '골루그를 만든 고대인에게 사람과 포켓몬을 지키도록 명령받았다고 전해진다.', 'It is said that Golurk were ordered to protect people and Pokémon by the ancient people who made them.'),
  ('kalos', 251, 10533, false, '날개와 발의 근육이 강해 작은 포켓몬을 붙잡은 채로 너끈히 날 수 있다.', 'The muscles in its wings and legs are strong. It can easily fly while gripping a small Pokémon.'),
  ('kalos', 262, 10531, false, '머리의 빨판으로 나뭇가지나 집의 처마 밑에 매달린다. 7종류의 음색을 나누어 쓴다.', 'It uses the sucker on its head to hang from a tree or from eaves. It can produce seven different tones.'),
  ('kalos', 311, 10534, false, '몸을 접고 날개를 펼치면 마치 제트기 같다. 음속으로 날 수 있다.', 'When it folds up its body and extends its wings, it looks like a jet plane. It flies at sonic speed.'),
  ('kalos', 331, 10504, false, '정글의 안쪽에 우츠보트만 있는 지대가 있어서 한 번 가면 두 번 다시 돌아올 수 없다.', 'Said to live in huge colonies deep in jungles, although no one has ever returned from there.'),
  ('kalos', 370, 10516, false, '샹델라의 불꽃에 둘러싸이면 영혼이 빨려가 불타버린다. 빈 껍데기인 몸만 남는다.', 'Being consumed in Chandelure’s flame burns up the spirit, leaving the body behind.'),
  ('kalos', 415, 10509, false, '가시나무 안에 둥지를 만든다. 가시에 상처를 입어가며 자라난 새끼들의 날개는 단단해진다.', 'After nesting in bramble bushes, the wings of its chicks grow hard from scratches by thorns.'),
  ('kalos', 450, 10506, false, '커다란 몸집으로 하늘을 난다. 지구를 약 16시간 만에 일주한다.', 'It can fly in spite of its big and bulky physique. It circles the globe in just 16 hours.'),
  ('kalos', 453, 10526, false, '칼로스지방의 생태계가 무너지면 모습을 나타내어 숨겨진 힘을 발휘한다고 한다.', 'When the Kalos region’s ecosystem falls into disarray, it appears and reveals its secret power.'),
  ('alola', 27, 10522, false, '강력한 최면술을 사용한다. 그것을 이용해 못된 짓을 하는 자들이 끊이지 않는다.', 'When it comes to strong hypnosis, there’s an endless number of people who utilize Malamar for their nefarious deeds.'),
  ('alola', 33, 10529, false, '몸에 전기가 쌓일수록 공격적으로 변한다. 사실은 전기가 스트레스라는 설도 있다.', 'As electricity builds up inside its body, it becomes more aggressive. One theory is that the electricity buildup is actually causing stress.'),
  ('alola', 33, 10530, false, '몸에 전기가 쌓일수록 공격적으로 변한다. 사실은 전기가 스트레스라는 설도 있다.', 'As electricity builds up inside its body, it becomes more aggressive. One theory is that the electricity buildup is actually causing stress.'),
  ('alola', 72, 10540, false, '집게 안에 냉기를 모아 때려눕힌다. 두꺼운 얼음벽도 가루로 만들어 버린다.', 'It stores coldness in its pincers and pummels its foes. It can even smash thick walls of ice to bits!'),
  ('alola', 96, 10525, false, '빠른 기술로 상대를 압도한다. 필살기를 쓰기 위한 어필이 너무 길어서 위기에 처하기도 한다.', 'It overwhelms opponents with quick moves, but sometimes it showboats for too long when it’s using a special move and gets itself into a pinch.'),
  ('alola', 101, 10521, false, '꽃을 길러 자신의 무기로 이용한다. 아름답게 핀 꽃일수록 강력한 파워를 간직하고 있다.', 'It raises flowers and uses them as weapons. The more gorgeous the blossom, the more power it contains.'),
  ('alola', 222, 10541, false, '몸을 덮고 있는 두꺼운 껍질은 다이아몬드 정도의 강도다. 이기기 위해서는 수단을 가리지 않는다.', 'The shell covering its body is as hard as diamond. This Pokémon will do anything it takes to win.'),
  ('alola', 224, 10505, false, '빛나는 코어는 바다의 보석이라고 불린다. 고가의 액세서리로 만들어져 은밀히 거래된다.', 'Its sparkling core is called “the gem of the sea.” This core can be made into high-priced accessories that are traded in secret.'),
  ('alola', 263, 10526, false, '지가르데의 일부가 반 정도 모인 모습이다. 생태계를 감시하는 역할을 맡고 있다.', 'This is Zygarde’s form when about half of its pieces have been assembled. It plays the role of monitoring the ecosystem.'),
  ('alola', 270, 10509, false, '빠진 날개를 가공해서 만드는 식칼은 일류 요리사도 인정할 정도로 날카롭다.', 'The wing feathers it sheds can be processed and made into knives whose sharpness is recognized by the finest chefs.'),
  ('alola', 274, 10503, false, '1km 떨어진 곳에서 바늘이 떨어지는 소리도 들을 수 있어 사람과 포켓몬이 적은 깊은 산속에 산다.', 'It can’t help but hear a pin drop from over half a mile away, so it lives deep in the mountains where there aren’t many people or Pokémon.'),
  ('alola', 309, 10534, false, '음속으로 날아다니며 먹이를 찾는다. 먹이를 두고 보만다와 공중전을 펼친다.', 'It flies at the speed of sound while searching for prey, and it has midair battles with Salamence as the two compete for food.'),
  ('alola', 313, 10538, false, '고대인이 노동력으로 활용하기 위해 골루그를 발명했다고 전해진다. 주인의 명령에 충실하다.', 'Some say that ancient people invented Golurk to serve as a laborer. It follows its master’s orders faithfully.'),
  ('alola', 321, 10527, false, '친구가 된 아이가 괴롭힘을 당하면 괴롭힌 아이의 집에 찾아가서 태워버린다.', 'If a child it has made friends with is bullied, Drampa will find the bully’s house and burn it to the ground.'),
  ('alola', 322, 10532, false, '비록 겉모습은 불길하지만 논밭을 지키거나 이변을 사람에게 알려 주는 고마운 존재다.', 'The only thing unlucky about Absol is its appearance. It protects fields and warns people of disaster, so one ought to be grateful for it.'),
  ('alola', 325, 10510, false, '설산에 등산 온 남자를 얼려버려 집으로 가지고 간다. 미남만 노린다.', 'It freezes hikers who have come to climb snowy mountains and carries them back to its home. It only goes after men it thinks are handsome.'),
  ('alola', 336, 10514, false, '거칠고 난폭하지만, 자신의 가족과 무리 동료의 영역을 매우 소중히 여기는 포켓몬이다.', 'This Pokémon may be rude, but it takes very good care of its family, its friends, and its turf.'),
  ('alola', 348, 10524, false, '매우 흉포해서, 다가온 상대에게 독액을 내뿜는다. 무슨 이유에서인지 타타륜과만 매우 사이가 좋다.', 'This vicious Pokémon sprays a poisonous liquid on opponents that come near. For whatever reason, it gets along really well with Dhelmise.'),
  ('alola', 371, 10520, false, '수컷은 평소에 빈둥거리지만, 강적이 덤벼들면 자신을 돌보지 않고 동료를 지킨다.', 'The males are usually lazy, but when attacked by a strong foe, a male will protect its friends with no regard for its own safety.'),
  ('alola', 378, 10535, false, '정신을 집중하고 발산하는 파동이라고 불리는 신비한 파는 큰 바위도 산산이 부숴 버린다.', 'It concentrates its mental energy and fires off mysterious waves called auras, which can crush boulders of large size to dust.'),
  ('alola', 381, 10506, false, '성난 바다도 아랑곳하지 않고 날아간다. 그 모습을 본 선장은 바다의 화신이라고 불렀다.', 'It flies over raging seas as if they were nothing. Observing this, a ship’s captain dubbed this Pokémon “the sea incarnate.”'),
  ('alola', 401, 10542, false, '의식을 동조시켜 상대의 마음을 이해한다. 사람을 도울 때 편리한 능력이다.', 'It synchronizes its consciousness with others to understand their feelings. This faculty makes it useful for taking care of people.'),
  ('alola', 401, 10543, false, '의식을 동조시켜 상대의 마음을 이해한다. 사람을 도울 때 편리한 능력이다.', 'It synchronizes its consciousness with others to understand their feelings. This faculty makes it useful for taking care of people.'),
  ('alola', 403, 10544, false, '양 손발톱에 전기를 머금어 상대를 갈가리 찢는다. 피하더라도 흩날리는 전격으로 감전시킨다.', 'It electrifies its claws and tears its opponents apart with them. Even if they dodge its attack, they’ll be electrocuted by the flying sparks.'),
  ('galar', 81, 10510, false, '설산에서 죽은 여자의 원념에서 태어난 포켓몬. 얼린 영혼을 즐겨 먹는다.', 'After a woman met her end on a snowy mountain, her regrets lingered on. From them, this Pokémon was born. Its favorite food is frozen souls.'),
  ('galar', 89, 10538, false, '고대인의 성벽에는 골루그가 빔을 쏘기 위한 포대와 같은 대좌가 있다.', 'Artillery platforms built into the walls of ancient castles served as perches from which Golurk could fire energy beams.'),
  ('galar', 167, 10512, false, '자연적으로 생긴 동굴로 보이지만 사실은 몰드류가 파낸 흔적인 경우는 흔히 있는 일이다.', 'It’s not uncommon for tunnels that appear to have formed naturally to actually be a result of Excadrill’s rampant digging.'),
  ('galar', 195, 10529, false, '긴 꼬리가 어스가 되어 몸을 지키기 때문에 자신은 고전압에도 마비되지 않는다.', 'Its long tail serves as a ground to protect itself from its own high-voltage power.'),
  ('galar', 195, 10530, false, '긴 꼬리가 어스가 되어 몸을 지키기 때문에 자신은 고전압에도 마비되지 않는다.', 'Its long tail serves as a ground to protect itself from its own high-voltage power.'),
  ('galar', 209, 10539, false, '귀 안쪽의 눈알 모양에서 사이코 파워를 내지만 평소에는 그 힘을 숨기고 있다.', 'Revealing the eyelike patterns on the insides of its ears will unleash its psychic powers. It normally keeps the patterns hidden, however.'),
  ('galar', 209, 10554, false, '귀 안쪽의 눈알 모양에서 사이코 파워를 내지만 평소에는 그 힘을 숨기고 있다.', 'Revealing the eyelike patterns on the insides of its ears will unleash its psychic powers. It normally keeps the patterns hidden, however.'),
  ('galar', 225, 10514, false, '의욕이 없어 보이는 킥은 노보청이 들고 있는 콘크리트도 부술 정도의 파괴력을 지녔다.', 'As halfhearted as this Pokémon’s kicks may seem, they pack enough power to shatter Conkeldurr’s concrete pillars.'),
  ('galar', 233, 10541, false, '이기기 위해서는 수단을 가리지 않는다. 상대의 빈틈을 찌른 뒤 앞발의 작은 발톱으로 마무리한다.', 'It will do anything to win, taking advantage of every opening and finishing opponents off with the small claws on its front legs.'),
  ('galar', 235, 10523, false, '7마리의 거북손손이 1마리의 몸을 이루고 있다. 머리가 손발에 명령하는 구조다.', 'Seven Binacle come together to form one Barbaracle. The Binacle that serves as the head gives orders to those serving as the limbs.'),
  ('galar', 256, 10503, false, '요정의 동료로 좀처럼 사람 앞에 나타나지 않는다. 기척을 느끼면 바로 도망가는 듯하다.', 'A timid fairy Pokémon that is rarely seen, it will run and hide the moment it senses people.'),
  ('galar', 289, 10516, false, '오래된 양옥집에 산다. 팔의 불꽃을 이상하게 흔들어서 상대에게 최면을 건다.', 'This Pokémon haunts dilapidated mansions. It sways its arms to hypnotize opponents with the ominous dancing of its flames.'),
  ('galar', 291, 10522, false, '발광체의 빛을 보면 순식간에 최면 상태가 되어 칼라마네로에게 조종당한다.', 'Gazing at its luminescent spots will quickly induce a hypnotic state, putting the observer under Malamar’s control.'),
  ('galar', 299, 10535, false, '큰 바위도 산산조각 내는 파동이라 불리는 힘을 다뤄서 먹이를 사냥한다.', 'It controls waves known as auras, which are powerful enough to pulverize huge rocks. It uses these waves to take down its prey.'),
  ('galar', 320, 10525, false, '경쾌한 몸놀림을 활용한 전법으로 상대의 체력을 빼앗은 뒤 화려한 큰 기술을 먹인다.', 'It drives its opponents to exhaustion with its agile maneuvers, then ends the fight with a flashy finishing move.'),
  ('galar', 345, 10528, false, '리더라고 불리는 1마리와 멤버라고 불리는 5마리로 이루어져 있다. 리더의 명령은 절대적이다.', 'Five of them are troopers, and one is the brass. The brass’s orders are absolute.'),
  ('galar', 346, 10527, false, '해발 3000m가 넘는 산에 산다. 드물게 마을로 내려와 아이들과 논다.', 'The mountains it calls home are nearly two miles in height. On rare occasions, it descends to play with the children living in the towns below.'),
  ('galar', 439, 10513, false, '목의 가시로 먹이를 잡은 채 그대로 땅으로 내동댕이쳐서 독가시를 꽂는다.', 'Scolipede latches on to its prey with the claws on its neck before slamming them into the ground and jabbing them with its claws’ toxic spikes.'),
  ('galar', 448, 10505, false, '강렬한 사이코 파워를 발산할 때 코어라고 불리는 기관이 일곱 색깔로 빛난다.', 'This Pokémon has an organ known as its core. The organ glows in seven colors when Starmie is unleashing its potent psychic powers.'),
  ('galar', 481, 10509, false, '날카로운 날개는 검보다 예리하다. 영역을 두고 아머까오와 격렬하게 싸운다.', 'The pointed feathers of these Pokémon are sharper than swords. Skarmory and Corviknight fight viciously over territory.'),
  ('galar', 497, 10524, false, '금속을 녹슬게 하는 독액으로 영역에 들어온 유조선을 바다의 부스러기로 만들어 버린다.', 'Dragalge uses a poisonous liquid capable of corroding metal to send tankers that enter its territory to the bottom of the sea.'),
  ('galar', 534, 10532, false, '바람처럼 산과 들을 달려나간다. 초승달 모양의 뿔은 자연재해의 징조를 민감하게 감지한다.', 'Swift as the wind, Absol races through fields and mountains. Its curved, bow-like horn is acutely sensitive to the warning signs of natural disasters.'),
  ('galar', 540, 10534, false, '화산이 있는 산에 서식한다. 제트기에도 지지 않는 속도로 하늘을 날아 먹이를 사냥한다.', 'Garchomp makes its home in volcanic mountains. It flies through the sky as fast as a jet airplane, hunting down as much prey as it can.'),
  ('galar', 570, 10506, false, '물에 빠진 사람이나 포켓몬을 발견하면 반드시 도와주는 마음 착한 포켓몬이다.', 'It’s a kindhearted Pokémon. If it spots a drowning person or Pokémon, Dragonite simply must help them.'),
  ('hisui', 14, 10533, false, '찌르호크가 되면 무리에서 떨어져 혼자서 살아간다. 강인한 날개를 가지고 있다.', 'It has left the flock, having gained strength enough to survive on its own. The astounding force with which Staraptor flies through the air allows it to carry away large, burly targets.'),
  ('hisui', 57, 10529, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('hisui', 57, 10530, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('hisui', 189, 10534, false, '지상에서도 움직임이 빠르다. 설산에서는 체온이 떨어지기 전에 먹이를 잡아 거처로 돌아간다.', 'Soars across the heavens at blinding speed—a magnificent sight! It has a feral disposition. Utmost caution is required if one meets a Garchomp out in the wilds.'),
  ('hisui', 196, 10531, false, '바람이 강해지면 나뭇가지나 처마 끝에 머리의 흡반으로 매달려 울기 시작한다. 긴 꼬리로 나무열매를 집어서 먹는다.', 'Can emit waves of air powerful enough to knock out prey taller than itself. I hypothesize that it amplifies the faint sound of wind within its body.'),
  ('hisui', 201, 10503, false, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.'),
  ('hisui', 207, 10510, false, '마이너스 50도의 냉기를 뿜어 먹이를 얼린 뒤 거처로 가져가서 가지런히 나열한다.', 'A Pokémon inhabited by the soul of a woman who died bearing a grudge in the snowy mountains. Legends of Froslass placing deathly curses on misbehaving men send shivers down my spine.'),
  ('hisui', 224, 10535, false, '사람이 생각하는 것도 알 수 있기 때문에 정직한 마음을 가진 트레이너만 따른다.', 'A most gallant-looking creature. It emits energy waves and controls them with precision, using them to sense even faraway beings. I have given the name ”aura” to this power.'),
  ('hisui', 228, 10536, false, '마그마처럼 타오르는 혈액이 몸에서 흐르고 있다. 화산의 동굴에 서식한다.', 'Stories tell of this Pokémon being birthed from the boiling magma within Mount Coronet. Its molten-steel body holds many mysteries.'),
  ('hisui', 242, 10537, false, '사람들을 깊은 잠으로 끌어들여 꿈을 꾸게 하는 능력을 가지고 있다. 그믐달이 뜨는 밤에 활동한다.', 'On a moonless night, a strange incident occurred in which every one of a village''s inhabitants suffered nightmares. The villagers attested that Darkrai appeared before them in these nightmares.'),
  ('paldea', 75, 10529, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('paldea', 75, 10530, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('paldea', 99, 10533, false, '찌르호크가 되면 무리에서 떨어져 혼자서 살아간다. 강인한 날개를 가지고 있다.', 'It has left the flock, having gained strength enough to survive on its own. The astounding force with which Staraptor flies through the air allows it to carry away large, burly targets.'),
  ('paldea', 119, 10540, false, '생각하기보다는 일단 때리고 본다. 눈사태를 펀치 러시로 되받아쳤다는 기록도 있다.', 'Before it stops to think, it just starts pummeling. There are records of its turning back avalanches with a flurry of punches.'),
  ('paldea', 128, 10534, false, '지상에서도 움직임이 빠르다. 설산에서는 체온이 떨어지기 전에 먹이를 잡아 거처로 돌아간다.', 'Soars across the heavens at blinding speed—a magnificent sight! It has a feral disposition. Utmost caution is required if one meets a Garchomp out in the wilds.'),
  ('paldea', 146, 10521, false, '자신의 파워를 꽃에 주고 진심을 담아 돌본다. 화단을 어지럽히는 자는 용서하지 않는다.', 'It gives its own power to flowers, pouring its heart into caring for them. Floette never forgives anyone who messes up a flower bed.'),
  ('paldea', 164, 10535, false, '사람이 생각하는 것도 알 수 있기 때문에 정직한 마음을 가진 트레이너만 따른다.', 'A most gallant-looking creature. It emits energy waves and controls them with precision, using them to sense even faraway beings. I have given the name ”aura” to this power.'),
  ('paldea', 225, 10520, false, '섭씨 6000도의 숨결을 내뱉지만 먹이에는 사용하지 않는다. 고기는 날것을 좋아하기 때문이다.', 'The temperature of its breath is over 10,000 degrees Fahrenheit, but Pyroar doesn’t use it on its prey. This Pokémon prefers to eat raw meat.'),
  ('paldea', 251, 10545, false, null, 'The red head converts spicy chemicals into fire energy and blasts the surrounding area with a super spicy stream of flame.'),
  ('paldea', 300, 10528, false, '6마리가 1마리의 포켓몬이다. 대열을 바꿔가며 팀워크로 싸운다.', 'The six of them work together as one Pokémon. Teamwork is also their battle strategy, and they constantly change their formation as they fight.'),
  ('paldea', 301, 10525, false, '끝을 내는 결정적인 기술을 쓰기 전에 반드시 포즈를 취한다. 그 틈에 반격당하기도 한다.', 'It always strikes a pose before going for its finishing move. Sometimes opponents take advantage of that time to counterattack.'),
  ('paldea', 309, 10546, false, null, 'When this Pokémon detects danger, it will open up its crystalline petals and fire beams from its conical body.'),
  ('paldea', 338, 10524, false, '머리의 갓을 해면 위로 내밀고 태양 빛을 받아 드래곤 에너지를 만든다.', 'Dragalge generates dragon energy by sticking the plume on its head out above the ocean’s surface and bathing it in sunlight.'),
  ('paldea', 343, 10515, false, '팔 힘으로 바다에서 기어 나와 물가에 있는 먹이를 덮친다. 한순간에 바다로 끌고 들어간다.', 'They crawl out of the ocean using their arms. They will attack prey on shore and immediately drag it into the ocean.'),
  ('paldea', 349, 10506, false, '바다의 화신이라고 불린다. 망나뇽 형태의 조각상을 뱃머리에 두는 배도 많다.', 'This Pokémon is known as the Sea Incarnate. Figureheads that resemble Dragonite decorate the bows of many ships.'),
  ('paldea', 359, 10510, false, '마이너스 50도의 냉기를 뿜어 먹이를 얼린 뒤 거처로 가져가서 가지런히 나열한다.', 'A Pokémon inhabited by the soul of a woman who died bearing a grudge in the snowy mountains. Legends of Froslass placing deathly curses on misbehaving men send shivers down my spine.'),
  ('paldea', 375, 10547, false, null, 'This is a small dragon Pokémon. It lives inside the mouth of Dondozo to protect itself from enemies on the outside.'),
  ('paldea', 375, 10548, false, null, 'This is a small dragon Pokémon. It lives inside the mouth of Dondozo to protect itself from enemies on the outside.'),
  ('paldea', 375, 10549, false, null, 'This is a small dragon Pokémon. It lives inside the mouth of Dondozo to protect itself from enemies on the outside.'),
  ('paldea', 390, 10550, false, null, 'This Pokémon blasts cryogenic air out from its mouth. This air can instantly freeze even liquid-hot lava.'),
  ('paldea', 421, 10504, false, '꿀 냄새로 먹이를 끌어들인다. 입안에 넣은 것은 하루 만에 뼈까지 녹여버린다고 한다.', 'Lures prey with the sweet aroma of honey. Swallowed whole, the prey is dissolved in a day, bones and all.'),
  ('paldea', 479, 10531, false, '바람이 강해지면 나뭇가지나 처마 끝에 머리의 흡반으로 매달려 울기 시작한다. 긴 꼬리로 나무열매를 집어서 먹는다.', 'Can emit waves of air powerful enough to knock out prey taller than itself. I hypothesize that it amplifies the faint sound of wind within its body.'),
  ('paldea', 484, 10516, false, '샹델라를 등불 대용으로 사용했던 저택에서는 장례식이 끊이지 않았다고 한다.', 'In homes illuminated by Chandelure instead of lights, funerals were a constant occurrence— or so it’s said.'),
  ('paldea', 487, 10503, false, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.'),
  ('paldea', 540, 10522, false, '역사를 바꿀 정도의 큰 사건은 칼라마네로의 최면 능력과 관련이 있다고 전해진다.', 'It’s said that Malamar’s hypnotic powers played a role in certain history-changing events.'),
  ('paldea', 548, 10512, false, '별명은 드릴킹이다. 땅속을 파는 속도는 시속 150km에 달한다.', 'Known as the Drill King, this Pokémon can tunnel through the terrain at speeds of over 90 mph.'),
  ('paldea', 550, 10539, false, '수컷은 방어 본능이 강해서 자신과 파트너를 지킬 때 최대의 파워를 쓴다.', 'The defensive instinct of the males is strong. It’s when they’re protecting themselves or their partners that they unleash their full power.'),
  ('paldea', 550, 10554, false, '수컷은 방어 본능이 강해서 자신과 파트너를 지킬 때 최대의 파워를 쓴다.', 'The defensive instinct of the males is strong. It’s when they’re protecting themselves or their partners that they unleash their full power.'),
  ('paldea', 558, 10509, false, '빠진 깃털로 검을 만들 수 있어서 문장 도안으로 인기가 많다.', 'People fashion swords from Skarmory’s shed feathers, so this Pokémon is a popular element in heraldic designs.'),
  ('paldea', 562, 10514, false, '매우 거친 성격이지만 가족과 동료와 영역은 소중히 여긴다.', 'While mostly known for having the temperament of an aggressive ruffian, this Pokémon takes very good care of its family, friends, and territory.'),
  ('paldea', 564, 10538, false, '체내에 에너지를 생성하는 영구 기관이 있다고 하지만 아직도 밝혀지지 않았다.', 'There’s a theory that inside Golurk is a perpetual motion machine that produces limitless energy, but this belief hasn’t been proven.'),
  ('paldea', 596, 10507, false, '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', 'The fragrance of Meganium’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit.'),
  ('paldea', 602, 10508, false, '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', 'Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.'),
  ('paldea', 626, 10511, false, '불꽃 턱수염을 기르고 있다. 파워와 스피드를 겸비한 격투 기술을 익히고 있다.', 'It has mastered fast and powerful fighting moves. It grows a beard of fire.'),
  ('paldea', 632, 10517, false, '얼굴 앞에 주먹을 맞대어 방어 포즈를 취하면 폭탄의 직격도 견뎌낸다.', 'When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.'),
  ('paldea', 635, 10518, false, '섭씨 3000도의 불꽃 소용돌이를 초능력으로 조종한다. 적을 소용돌이로 감싸 불태운다.', 'Using psychic power, it generates a fiery vortex of 5,400 degrees Fahrenheit, incinerating foes swept into this whirl of flame.'),
  ('paldea', 638, 10519, false, '닌자처럼 신출귀몰하다. 재빠른 움직임으로 상대를 농락하면서 물의 수리검으로 벤다.', 'It appears and vanishes with a ninja’s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.'),
  ('lumiose', 1, 152, true, '잎사귀를 휘둘러 상대를 위협하지만 잎사귀에서 달콤한 향기가 풍겨 나와 서로 온화한 분위기가 된다.', 'In battle, Chikorita waves its leaf around to keep the foe at bay. However, a sweet fragrance also wafts from the leaf, becalming the battling Pokémon and creating a cozy, friendly atmosphere all around.'),
  ('lumiose', 2, 153, true, '목 주변의 둥그렇게 말린 잎사귀 안에는 작은 새싹 한 개가 나 있다. 그 향기는 사람을 기운 나게 한다.', 'Bayleef’s neck is ringed by curled-up leaves. Inside each tubular leaf is a small shoot of a tree. The fragrance of this shoot makes people peppy.'),
  ('lumiose', 3, 154, true, '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', 'The fragrance of Meganium’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit.'),
  ('lumiose', 3, 10507, false, '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', 'The fragrance of Meganium’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit.'),
  ('lumiose', 4, 498, true, '구운 나무열매를 먹는 것을 매우 좋아하지만 너무 흥분해서 가끔 새까맣게 태워버린다.', 'It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.'),
  ('lumiose', 5, 499, true, '체내의 불꽃이 타오르면 움직임이 더 빠르고 예리해진다. 위급해지면 연기를 뿜어낸다.', 'When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.'),
  ('lumiose', 6, 500, true, '불꽃 턱수염을 기르고 있다. 파워와 스피드를 겸비한 격투 기술을 익히고 있다.', 'It has mastered fast and powerful fighting moves. It grows a beard of fire.'),
  ('lumiose', 6, 10511, false, '불꽃 턱수염을 기르고 있다. 파워와 스피드를 겸비한 격투 기술을 익히고 있다.', 'It has mastered fast and powerful fighting moves. It grows a beard of fire.'),
  ('lumiose', 7, 158, true, '몸은 작지만 턱의 힘은 강하다. 리아코 나름은 살포시 물려고 하지만 큰 상처를 입힐 정도의 힘이 있다.', 'Despite the smallness of its body, Totodile’s jaws are very powerful. While the Pokémon may think it is just playfully nipping, its bite has enough power to cause serious injury.'),
  ('lumiose', 8, 159, true, '한 번 물고 늘어지면 절대로 놓지 않는다. 이빨 끝이 낚싯바늘처럼 휘어져 있어서 한 번 들어가면 빠지지 않는다.', 'Once Croconaw has clamped its jaws on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like barbed fishhooks, they become impossible to remove when they have sunk in.'),
  ('lumiose', 9, 160, true, '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', 'Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.'),
  ('lumiose', 9, 10508, false, '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', 'Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.'),
  ('lumiose', 10, 661, true, '흥분하면 체온이 확 오른다. 맨손으로 만지면 화상을 입기도 할 정도다.', 'When this Pokémon gets excited, its body temperature increases sharply. If you touch a Fletchling with bare hands, you might get burned.'),
  ('lumiose', 11, 662, true, '영역에 대한 개념이 매우 강하고 호전적이다. 먹이 먹는 장소를 두고 불화살빈끼리 싸운다.', 'Fletchinder are exceedingly territorial and aggressive. These Pokémon fight among themselves over feeding grounds.'),
  ('lumiose', 12, 663, true, '시속 500km로 돌격한다. 먹이가 도망칠 틈을 주지 않고 강렬한 발차기로 꼼짝 못 하게 한다.', 'Talonflame dives toward prey at speeds of up to 310 mph and assaults them with powerful kicks, giving the prey no chance to escape.'),
  ('lumiose', 13, 659, true, '위험에 민감하다. 아머까오의 날갯소리를 들으면 눈 깜짝할 사이에 구멍을 파고 땅으로 숨어든다.', 'It’s very sensitive to danger. The sound of Corviknight’s flapping will have Bunnelby digging a hole to hide underground in moments.'),
  ('lumiose', 14, 660, true, '배의 털은 보온성이 뛰어나다. 옛날 사람들은 파르토의 몸에서 빠진 털로 방한복을 만들었다.', 'The fur on its belly retains heat exceptionally well. People used to make heavy winter clothing from fur shed by this Pokémon.'),
  ('lumiose', 15, 664, true, '몸을 덮은 가루가 체온을 조절하고 있어 어떤 기후나 풍토의 지역에서도 살 수 있다.', 'The powder that covers its body regulates its temperature, so it can live in any region or climate.'),
  ('lumiose', 16, 665, true, '단단한 몸은 새포켓몬의 부리로도 상처 하나 입지 않는다. 가루를 뿌려서 방어한다.', 'The beaks of bird Pokémon can’t begin to scratch its stalwart body. To defend itself, it spews powder.'),
  ('lumiose', 17, 666, true, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
  ('lumiose', 17, 10086, false, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
  ('lumiose', 17, 10087, false, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
  ('lumiose', 17, 10088, false, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
