on conflict (id) do update set
  slug = excluded.slug,
  ko_name = excluded.ko_name,
  en_name = excluded.en_name,
  ko_form_name = excluded.ko_form_name,
  en_form_name = excluded.en_form_name,
  form_of = excluded.form_of,
  ko_genus = excluded.ko_genus,
  en_genus = excluded.en_genus,
  generation = excluded.generation,
  category = excluded.category,
  type1 = excluded.type1,
  type2 = excluded.type2,
  hp = excluded.hp,
  attack = excluded.attack,
  defense = excluded.defense,
  special_attack = excluded.special_attack,
  special_defense = excluded.special_defense,
  speed = excluded.speed,
  height = excluded.height,
  weight = excluded.weight,
  growth_rate = excluded.growth_rate,
  capture_rate = excluded.capture_rate,
  hatch_counter = excluded.hatch_counter,
  gender_rate = excluded.gender_rate,
  evolves_from_id = excluded.evolves_from_id,
  evolution_method = excluded.evolution_method,
  sprites = excluded.sprites;

on conflict (id) do update set
  ko_name = excluded.ko_name,
  en_name = excluded.en_name;

on conflict (dex, species_id) do update set
  number = excluded.number,
  is_default = excluded.is_default,
  ko_description = excluded.ko_description,
  en_description = excluded.en_description;
